"""Separately authored functional inventory. Status is filled from JUnit."""

from __future__ import annotations


def _case(number: int, function: str, title: str, preconditions: str, steps: str, inputs: str, expected: str, trace: str) -> dict:
    return {
        "id": f"FC-{number:02d}",
        "function": function,
        "category": "Functional",
        "title": title,
        "preconditions": preconditions,
        "steps": steps,
        "inputs": inputs,
        "expected": expected,
        "trace": trace,
    }


